Method.Implementation:
    &html<
    	<!DOCTYPE html>
		<html lang="en">
		<head>
			<meta charset="utf-8">
			<meta http-equiv="X-UA-Compatible" content="IE=edge">
			<meta name="viewport" content="width=device-width, initial-scale=1">
			<meta name="description" content="">
			<meta name="author" content="">
			
			
			<link rel="stylesheet" href="https://maxcdn.bootstrapcdn.com/bootstrap/3.3.7/css/bootstrap.min.css" integrity="sha384-BVYiiSIFeK1dGmJRAkycuHAHRg32OmUcww7on3RYdg4Va+PmSTsz/K68vbdEjh4u" crossorigin="anonymous">
			<!-- Optional theme -->
			<link rel="stylesheet" href="https://maxcdn.bootstrapcdn.com/bootstrap/3.3.7/css/bootstrap-theme.min.css" integrity="sha384-rHyoN1iRsVXV4nD0JutlnGaslCJuC7uwjduW9SVrLvRYooPp2bWYgmgJQIXwl/Sp" crossorigin="anonymous">
			
			<link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/4.7.0/css/font-awesome.min.css">
			
			<!-- Latest compiled and minified JavaScript -->
			<script src="https://ajax.googleapis.com/ajax/libs/jquery/3.2.1/jquery.min.js"></script>
			<script src="https://maxcdn.bootstrapcdn.com/bootstrap/3.3.7/js/bootstrap.min.js" integrity="sha384-Tc5IQib027qvyjSMfHjOMaLkfuWVxZxUPnCJA7l2mCWNIpG9mGCD8wGNIcPD7Txa" crossorigin="anonymous"></script>
			<!-- HTML5 Shim and Respond.js IE8 support of HTML5 elements and media queries -->
			<!-- WARNING: Respond.js doesn't work if you view the page via file:// -->
			<!--[if lt IE 9]>
			        <script src="https://oss.maxcdn.com/libs/html5shiv/3.7.0/html5shiv.js"></script>
			        <script src="https://oss.maxcdn.com/libs/respond.js/1.4.2/respond.min.js"></script>
			
			    <![endif]-->
			<!-- jQuery -->
			>
			
			Write !, $$$cspBrokerInsertHttpJS
			&html<
			<script language="JavaScript" type="text/javascript">
				$(function() {
					//twitter bootstrap script
					$('#deploy-form').submit(function(e) {
						e.preventDefault();
						
						$('#deploy-btn').prop('disabled', true);
						$('.fa-spin').show();
						
						var username = $('#svn-username').val();
						var password = $('#svn-password').val();
						var jsonString = $('#deploy-json').val();
						
						var tempJSON = JSON.parse(jsonString);
						
						tempJSON.ldapUsername = btoa(username);
						tempJSON.ldapPassword = btoa(password);
						
						var formData = JSON.stringify(tempJSON);
						
						
						$.ajax({
				            type        : 'POST', // define the type of HTTP verb we want to use (POST for our form)
				            url         : '/eai/deploy/DeployAPI/deploy-package/', // the url where we want to POST
				            contentType	: 'application/json',
				            beforeSend	: function(xhr) { xhr.setRequestHeader("Authorization", "Basic " + btoa(username + ":" + password)); },
				            data        : formData, // our data object
				            dataType    : 'json', // what type of data do we expect back from the server
				            encode      : true
				        })
					        // using the done promise callback
					        .done(function(data) {
	
					        	// log data to the console so we can see
			                	console.log(data); 

				                // here we will handle errors and validation messages
						        if ( ! data.success) {
						            // handle errors ---------------
						            $('#superhero-group').append('<div class="alert alert-danger">' + data.message+ '</div>');
						            $('#deploy-btn').prop('disabled', false);
						            $('.fa-spin').hide();
						        } else {
						            // ALL GOOD! just show the success message!
						            $('form').append('<div class="alert alert-success">' + data.message + '</div>');
						            $('#deploy-btn').prop('disabled', false);
						            $('.fa-spin').hide();

						            // usually after form submission, you'll want to redirect
						            // window.location = '/thank-you'; // redirect a user to another page
						            //alert('Successfully deployed package!'); // for now we'll just alert the user
						
						        }
			            });
										
						return false;
				    });
				});
			</script>
			
			
			<style>
				.deploy-btn {
					font-size:72px;
				}
				#deployJSON {
					height: 300px;
					width: 500px;
				}
			</style>
		</head>
		<body>	
			<div class="container">
				<div style="margin-top:10px;">
					<form id="deploy-form" name="deploy-form" class="form-horizontal">
						<fieldset>
							<!-- Form Name -->
							<legend><h1>EAI Ensemble Deployment</h1></legend>
							
							<!-- Textarea -->
							<div class="form-group">
								<label class="col-md-4 control-label" for="deploy-json">Deploy JSON</label>
								<div class="col-md-4">                     
									<textarea class="form-control" id="deploy-json" name="deploy-json" style="height:400px;width:600px;"></textarea>
								</div>
							</div>
							
							<!-- Text input-->
							<div class="form-group">
							<label class="col-md-4 control-label" for="svn-username">SVN Username</label>  
							<div class="col-md-4">
							<input id="svn-username" name="svn-username" type="text" placeholder="Username" class="form-control input-md" required="">
							<span class="help-block">Enter your SVN username</span>  
							</div>
							</div>
							
							<!-- Password input-->
							<div class="form-group">
							<label class="col-md-4 control-label" for="svn-password">SVN Password</label>
							<div class="col-md-4">
							<input id="svn-password" name="svn-password" type="password" placeholder="Password" class="form-control input-md" required="">
							<span class="help-block">Enter your SVN password</span>
							</div>
							</div>
							
							
							<!-- Text input-->
							<!--div class="form-group">
							<label class="col-md-4 control-label" for="deployPackage">Deployment Package</label>  
							<div class="col-md-4">
							<input id="deployPackage" name="deployPackage" type="text" placeholder="Deploy package" class="form-control input-md">
							<span class="help-block">Enter the deploy package</span>  
							</div>
							</div-->
							
							<!-- Select Basic -->
							<!--div class="form-group">
							<label class="col-md-4 control-label" for="namespace">Namespace</label>
							<div class="col-md-4">
							<select id="namespace" name="namespace" class="form-control">
							<option value="ADT">ADT</option>
							<option value="ADT_IN">ADT_IN</option>
							<option value="BILLING">BILLING</option>
							<option value="DEMOGRAPHICS">DEMOGRAPHICS</option>
							<option value="LAB">LAB</option>
							<option value="MISC">MISC</option>
							<option value="ORDERS">ORDERS</option>
							<option value="PAYER">PAYER</option>
							<option value="PROVIDER">PROVIDER</option>
							<option value="RESULTS">RESULTS</option>
							</select>
							</div>
							</div-->
						
						
							<!-- Button -->
							<div class="form-group">
								<label class="col-md-4 control-label" for="deployButton"></label>
								<div class="col-md-4">
									<button id="deploy-btn" name="deploy-btn" type="submit" class="btn btn-primary btn-lg">Deploy <i style="display:none;" class="fa fa-gear fa-spin"></i></button>
								</div>
							</div>
						</fieldset>
					</form>
				</div>
			</div>
		</body>
		</html>
   
	>
    Quit $$$OK

Set tStatus = $$$OK
Try {
	
	Set tStatus = ##class(IHC.EAI.Deployment.UnitTest).DeployPackage(pUsername,pPassword)
	$$$ThrowOnError(tStatus)
	
} Catch eException {
	Set tStatus = eException.AsStatus()
}
Quit tStatus
